-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.deathknight.blood.Name"] = "Empfohlen"
L["rm.mop.deathknight.blood.Description"] = "Empfohlen für Bluttanks, gewählt in der Spezialisierung Blut. Zieht aus der Distanz mit Ausbruch, Eisiger Berührung oder Todesgriff. Todesstoß unter halber Gesundheit, wann immer Blutschild fehlt (ab 80), und bevor alle vier Frost- und Unheilig-Runen voll sind; Runenstoß bei fast 90 Runenmacht (Todesmantel bei 80, bevor Sie ihn erlernen); Ausbruch, sonst Eisige Berührung und Seuchenstoß, für Krankheiten und Siedendes Blut, um sie ab 68 zu erneuern; Seelenernter unter 35 %; Herzstoß (Blutstoß vor Stufe 60) bei zwei Blutrunen; Scharlachrote Geißel für Tod und Verfall, solange die Krankheiten anhalten, sonst Siedendes Blut; Blutwandlung bei elf Aufladungen; dann Todesstoß, Herzstoß, Runenstoß und Horn des Winters. Drei Gegner gegen Sie: Tod und Verfall, ein Verbreiten der Krankheiten (Siedendes Blut mit Wallendem Blut, sonst Pestilenz) und Siedendes Blut. Erinnerungen: Blutpräsenz, wenn Sie keine haben, Knochenschild, Horn des Winters, Gedankenfrost, Runenheilung, Vampirblut, Eisige Gegenwehr, Runenwaffe verstärken und Todespakt je nach Ihrer Gesundheit, Tanzende Runenwaffe gegen Elitegegner, Armee der Toten vor einem Gruppenboss. Sie kann eingehenden Schaden nicht sehen, daher liegen Antimagische Hülle (deaktiviert) und große Defensivfähigkeiten bei Ihnen."
L["rm.mop.deathknight.blood.simulator.Name"] = "Reagiert auf Gesundheit (Simulation)"
L["rm.mop.deathknight.blood.simulator.Description"] = "Eine Alternative zur empfohlenen integrierten Blutrotation für Schlachtzugstanks mit Heilern, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Todesstoß nur unter 70 % Gesundheit, wenn Blutschild fehlt oder bald ausläuft oder bevor die Frost- und Unheilig-Runen voll sind, statt bei jeder Rune; eine einzelne Blutrune geht in Herzstoß, wenn die Frost- und Unheilig-Runen mehr als eine Sekunde entfernt sind. Sie hat keinen Abschnitt für Flächenschaden und dieselben Erinnerungen wie die empfohlene."
L["rm.mop.deathknight.frost.Name"] = "Zweihandwaffe"
L["rm.mop.deathknight.frost.Description"] = "Frost mit einer Zweihandwaffe, die übliche Ausstattung beim Leveln; gewählt in der Spezialisierung Frost, wann immer die integrierte Rotation für zwei Waffen nicht greift. Dieselbe Eröffnung, dieselben Krankheiten, dasselbe Überleben und derselbe Flächenschaden wie bei der integrierten Rotation für zwei Waffen, dann Auslöschen bei Tötungsmaschine, Froststoß über 76 Runenmacht, Heulende Böe bei Raureif, Auslöschen, wann immer ein Runenpaar voll ist, Auslöschen, Heulende Böe, Seuche entziehen, Froststoß bei 40 und Horn des Winters. Vor Auslöschen (Stufe 58) verbraucht Todesstoß Ihre Unheilig-Runen. Dieselben Erinnerungen wie die integrierte Rotation für zwei Waffen."
L["rm.mop.deathknight.frost.dualwield.Name"] = "Zwei Waffen"
L["rm.mop.deathknight.frost.dualwield.Description"] = "Empfohlen für Frost mit zwei Einhandwaffen (Masterfrost); gewählt in der Spezialisierung Frost, solange Ihre Schildhand eine Waffe hält. Zieht mit Ausbruch oder Heulender Böe (Todesgriff solo). Todesstoß bei Finsterer Beistand oder unter 35 % Gesundheit, Blutwandlung bei elf Aufladungen, Krankheiten (Unheilige Verseuchung, Ausbruch, Heulende Böe, Seuchenstoß), Seelenernter unter 35 %, Froststoß bei Tötungsmaschine oder über 89 Runenmacht, Heulende Böe bei Raureif oder wenn beide Frost- oder beide Todesrunen bereit sind, Auslöschen bei zwei Unheilig-Runen unter 77 Runenmacht, Froststoß über 76, Auslöschen, Heulende Böe, Seuche entziehen, bevor die Krankheiten auslaufen und Ausbruch bereit ist, Froststoß bei 40, Horn des Winters. Drei Gegner gegen Sie: ein Verbreiten der Krankheiten, Tod und Verfall und Heulende Böe. Erinnerungen: Frostpräsenz, Säule des Frosts, Totenerweckung, Runenwaffe verstärken, wenn alle Runen verbraucht sind, Horn des Winters, Gedankenfrost, Eisige Gegenwehr und Todespakt bei niedriger Gesundheit, Armee der Toten vor einem Gruppenboss."
L["rm.mop.deathknight.unholy.Name"] = "Unheilig"
L["rm.mop.deathknight.unholy.Description"] = "Empfohlen für Unheilig und die integrierte Rotation für jeden Todesritter, den Blut und Frost nicht beanspruchen, auch einen ohne Spezialisierung. Zieht aus der Distanz mit Ausbruch oder Eisiger Berührung (Todesgriff solo). Todesstoß bei Finsterer Beistand oder unter 35 % Gesundheit, Krankheiten (Unheilige Verseuchung, Ausbruch, Seuchenstoß, Eisige Berührung), Blutwandlung bei elf Aufladungen, Seelenernter unter 35 %, Dunkle Transformation bei fünf Stapeln Schattenmacht, Todesmantel nahe der maximalen Runenmacht, Tod und Verfall auf ein Ziel, das lange genug lebt, Geißelstoß, Todesmantel bei Hereinbrechender Verdammnis oder bei 40, Ausbruch, solange Unheilige Stärke aktiv ist, Schwärender Stoß (Blutstoß, bevor Sie ihn erlernen), Seuche entziehen, Horn des Winters. Drei Gegner gegen Sie: ein Verbreiten der Krankheiten, Tod und Verfall, Siedendes Blut und Eisige Berührung mit einer Frostrune. Erinnerungen: Unheilige Präsenz, Ihr Ghul, Gargoyle beschwören während Kampfrausch oder bei einem langen Kampf gegen Elitegegner, Unheilige Raserei, Runenwaffe verstärken, Horn des Winters, Gedankenfrost, Eisige Gegenwehr und Todespakt bei niedriger Gesundheit, Armee der Toten vor einem Gruppenboss; Antimagische Hülle ist deaktiviert."
L["rm.mop.deathknight.unholy.simulator.Name"] = "Unheilig, Runen bis zum Maximum sammeln (Simulation)"
L["rm.mop.deathknight.unholy.simulator.Description"] = "Eine Alternative zur empfohlenen integrierten Unheilig-Rotation, wie der Simulator, wowtbc.gg, Method und MaxDps sie spielen; standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Solange Dunkle Transformation nicht aktiv ist, dient Todesmantel dem Neuaufbau von Schattenmacht, Geißelstoß kommt zuerst, wenn beide Unheilig- oder beide Todesrunen bereit sind, und Schwärender Stoß zuerst, wenn beide Blut- und beide Frostrunen bereit sind; ansonsten dieselbe Eröffnung, dieselben Krankheiten, derselbe Flächenschaden und dieselben Erinnerungen wie die empfohlene."
L["rm.retail.deathknight.blood.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.deathknight.blood.Description"] = "Empfohlen für Blut. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Vampirblut und Totenerweckung im Kampf, Gedankenfrost bei einem unterbrechbaren Zauber sowie Eisige Gegenwehr und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Gedankenfrost nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Eisiger Gegenwehr Ihnen überlassen. Das Timing der aktiven Schadensminderung, Antimagische Hülle, Spotten und Schmuckstücke bleiben Ihnen überlassen."
L["rm.retail.deathknight.blood.guide.Name"] = "Referenz (Icy Veins und Wowhead)"
L["rm.retail.deathknight.blood.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Blut. Im Kampf in Midnight sind Ihre Stärkungszauber und die Schwächungszauber des Ziels für Addons verborgen, daher warten die Schritte, die sie lesen, dort; lesen Sie sie, oder duplizieren Sie sie, um damit zu experimentieren. Gesundheit und Runenmacht sind unter Retail verborgen, daher wird Todesstoß eingesetzt, wann immer Sie es sich leisten können. Zieht mit Hand des Todes. Todesstoß; Markzerfetzer (Hand des Todes außerhalb des Nahkampfs), wenn Knochenschild fehlt, unter fünf Aufladungen liegt, bald ausläuft oder Exterminieren aktiv ist; während Gabe der San'layn Todesstoß, einmal Siedendes Blut, Tod und Verfall bei Scharlachroter Geißel und Herzstoß; Tod und Verfall bei Scharlachroter Geißel oder gegen vier Gegner; Vampirstoß; Schwindsucht; Siedendes Blut bei Siedepunkt, fehlender Blutseuche oder vollen Aufladungen; Herzstoß. Erinnerungen: Totenerweckung, Vampirblut, Mal des Schnitters, Tanzende Runenwaffe nach Mal des Schnitters, dazu die Erinnerungen an Hilfsfähigkeiten aus der integrierten Kampfassistent-Rotation."
L["rm.retail.deathknight.blood.simc.Name"] = "Todesbringer-Referenz (SimulationCraft)"
L["rm.retail.deathknight.blood.simc.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Todesbringer-Liste von SimulationCraft, die Runenmacht für Schaden in Todesstoß steckt. Verborgene Kampfdaten verhindern, dass sie im Kampf in Midnight läuft, und Runenmacht ist unter Retail verborgen, daher gibt es keinen Abbau an der Obergrenze. Tod und Verfall, wann immer der Effekt fehlt, Mal des Schnitters, Markzerfetzer bei Exterminieren, Hand des Todes für Knochenschild bei knappen Runen (sonst Markzerfetzer), Todesstoß, Siedendes Blut, Schwindsucht außerhalb von Tanzender Runenwaffe, Herzstoß. Erinnerungen: Totenerweckung, Tanzende Runenwaffe, Vampirblut und die Erinnerungen an Hilfsfähigkeiten."
L["rm.retail.deathknight.frost.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.deathknight.frost.Description"] = "Empfohlen für Frost. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Sindragosas Hauch und Totenerweckung im Kampf, Gedankenfrost bei einem unterbrechbaren Zauber sowie Eisige Gegenwehr und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Gedankenfrost nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Eisiger Gegenwehr Ihnen überlassen."
L["rm.retail.deathknight.frost.guide.Name"] = "Referenz (Icy Veins und SimulationCraft)"
L["rm.retail.deathknight.frost.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Frost. Tötungsmaschine, Raureif und Schneidendes Eis sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen; Runenmacht ist unter Retail verborgen, daher gibt es keine Prüfung der Obergrenze. Auslöschen bei zwei Stapeln Tötungsmaschine oder einem mit drei Runen, Froststoß bei fünf Stapeln Schneidendes Eis mit Zertrümmernder Klinge, Heulende Böe bei Raureif, Auslöschen bei Tötungsmaschine, Froststoß, Auslöschen; gegen drei oder mehr Gegner werden Frostsichel und Unaufhaltbarer Gletscher eingewechselt; Heulende Böe außerhalb des Nahkampfs. Erinnerungen: Unbarmherziger Winter, Säule des Frosts, Sindragosas Hauch und Furor des Frostwyrms während der Säule, Mal des Schnitters, Totenerweckung, Runenwaffe verstärken bei zwei Aufladungen, dazu die Erinnerungen an Hilfsfähigkeiten."
L["rm.retail.deathknight.frost.wowhead.Name"] = "Referenz (Wowhead)"
L["rm.retail.deathknight.frost.wowhead.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Wowhead für Frost, die ihre Abklingzeiten in die Rotation aufnimmt. Verborgene Kampfdaten verhindern, dass sie im Kampf in Midnight läuft; Runenmacht ist unter Retail verborgen, daher gibt es keine Prüfung der Obergrenze. Runenwaffe verstärken bei zwei Aufladungen, Mal des Schnitters, Säule des Frosts, Sindragosas Hauch, Furor des Frostwyrms; dann Auslöschen bei zwei Stapeln Tötungsmaschine oder einem mit Exterminieren, Heulende Böe bei Raureif, Auslöschen bei Tötungsmaschine, Runenwaffe verstärken für eine neue Tötungsmaschine, Froststoß, Auslöschen, Heulende Böe. Gegen drei oder mehr Gegner werden Frostsichel und Unaufhaltbarer Gletscher eingewechselt."
L["rm.retail.deathknight.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.deathknight.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Todesritters meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Todesritter-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.retail.deathknight.unholy.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.deathknight.unholy.Description"] = "Empfohlen für Unheilig. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt (er erweckt Ihren Ghul und nutzt Armee der Toten und Dunkle Transformation selbst); sie wartet, während Sie wirken oder kanalisieren. Daneben: Gedankenfrost bei einem unterbrechbaren Zauber sowie Eisige Gegenwehr und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Gedankenfrost nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Eisiger Gegenwehr Ihnen überlassen."
L["rm.retail.deathknight.unholy.guide.Name"] = "Referenz (Icy Veins und Wowhead)"
L["rm.retail.deathknight.unholy.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Unheilig. Procs und Seuchen sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen; Runenmacht und die Gesundheit des Ziels sind unter Retail verborgen, daher entfallen das Hinrichtungsfenster und der Runenmacht-Einsatz der San'layn. Totenerweckung ohne Ghul; Schwärende Sense, um das Tempo ihrer Seuche aufrechtzuerhalten; Seelenernter bei Ernte; Verwesen während Dunkler Transformation; Todesmantel (Epidemie gegen vier oder mehr Gegner) bei Hereinbrechender Verdammnis oder Verbotenem Wissen; Schwärender Stoß ohne Aufladungen von Niederer Ghul, Geißelstoß mit ihnen; Todesmantel. Erinnerungen: Armee der Toten, Dunkle Transformation, Ausbruch, wenn Ihre Seuchen fehlen, dazu die Erinnerungen an Hilfsfähigkeiten."
L["rm.retail.deathknight.unholy.simc.Name"] = "Referenz (SimulationCraft)"
L["rm.retail.deathknight.unholy.simc.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Liste von SimulationCraft für Unheilig, die Todesmantel weit häufiger einsetzt. Verborgene Kampfdaten verhindern, dass sie im Kampf in Midnight läuft; Runenmacht und die Gesundheit des Ziels sind unter Retail verborgen, daher entfallen die Prüfungen von Obergrenze und Hinrichtung. Schwärende Sense aufrechterhalten, Seelenernter während Dunkler Transformation, Todesmantel bei Hereinbrechender Verdammnis, Verwesen während Dunkler Transformation, Todesmantel während Dunkler Transformation oder Verbotenem Wissen und immer, wenn Armee der Toten erst in mehr als 5 Sekunden bereit ist, Geißelstoß mit Aufladungen von Niederer Ghul, Schwärender Stoß. Drei oder mehr Gegner: Epidemie statt Todesmantel und Schwärender Stoß unter drei Aufladungen. Erinnerungen: Ausbruch, Tod und Verfall gegen Gruppen, Armee der Toten, Dunkle Transformation."
